SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 DESC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_CATEGORY" LEFT OUTER JOIN "DATETIMES_ARTICLE_CATEGORIES" ON ("DATETIMES_CATEGORY"."ID" = "DATETIMES_ARTICLE_CATEGORIES"."CATEGORY_ID") LEFT OUTER JOIN "DATETIMES_ARTICLE" ON ("DATETIMES_ARTICLE_CATEGORIES"."ARTICLE_ID" = "DATETIMES_ARTICLE"."ID") WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_COMMENT" INNER JOIN "DATETIMES_ARTICLE" ON ("DATETIMES_COMMENT"."ARTICLE_ID" = "DATETIMES_ARTICLE"."ID") WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
