SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'MONTH') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'MONTH') AS "DATETIMEFIELD" FROM "DATETIMES_COMMENT" INNER JOIN "DATETIMES_ARTICLE" ON ("DATETIMES_COMMENT"."ARTICLE_ID" = "DATETIMES_ARTICLE"."ID") WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'YEAR') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_ARTICLE"."PUB_DATE", 'YEAR') AS "DATETIMEFIELD" FROM "DATETIMES_COMMENT" INNER JOIN "DATETIMES_ARTICLE" ON ("DATETIMES_COMMENT"."ARTICLE_ID" = "DATETIMES_ARTICLE"."ID") WHERE "DATETIMES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_COMMENT"."APPROVAL_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" LEFT OUTER JOIN "DATETIMES_COMMENT" ON ("DATETIMES_ARTICLE"."ID" = "DATETIMES_COMMENT"."ARTICLE_ID") WHERE "DATETIMES_COMMENT"."APPROVAL_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("DATETIMES_COMMENT"."PUB_DATE", 'DD') AS "DATETIMEFIELD" FROM "DATETIMES_ARTICLE" LEFT OUTER JOIN "DATETIMES_COMMENT" ON ("DATETIMES_ARTICLE"."ID" = "DATETIMES_COMMENT"."ARTICLE_ID") WHERE "DATETIMES_COMMENT"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
